import json, re
nb = json.load(open("notebooks/ceridwen_integrated_photometry_spectra.ipynb"))
for i, c in enumerate(nb["cells"]):
    if c["cell_type"] != "code": continue
    for ln, line in enumerate("".join(c["source"]).splitlines(), 1):
        if re.search(r"zred|sigma_smooth|fix_z|z_fixed|fixed_z", line):
            print(f"cell {i}:{ln}: {line}")
EOF",
  "description": "Find zred and sigma_smooth usage in the notebook"
}

